class Student:
    def __init__(self, name):
        self.name = name
    def average(self, marks):
        avg = sum(marks) / len(marks)
        print(f"Average for {self.name}: {avg}")

# Example usage
s = Student("Alice")
s.average([85, 92, 78, 90])

